fn normalize_bucket_count(value: usize) -> usize {
    match value {
        0 | 1 => value,
        _ => value
            .checked_next_power_of_two()
            .expect("bucket count overflow"),
    }
}

pub fn required_bucket_count(
    len: usize,
    max_load_factor: f32,
    minimum_buckets: usize,
) -> usize {
    if len == 0 {
        return normalize_bucket_count(minimum_buckets);
    }

    let mut buckets = normalize_bucket_count(minimum_buckets).max(1);
    while (len as f32) / (buckets as f32) > max_load_factor {
        buckets = buckets.checked_mul(2).expect("bucket count overflow");
    }

    buckets
}

#[cfg(test)]
mod tests {
    use super::required_bucket_count;

    #[test]
    fn grows_with_default_load_factor() {
        assert_eq!(required_bucket_count(0, 0.875, 0), 0);
        assert_eq!(required_bucket_count(1, 0.875, 0), 2);
        assert_eq!(required_bucket_count(11, 0.875, 0), 16);
        assert_eq!(required_bucket_count(15, 0.875, 0), 32);
    }

    #[test]
    fn rehashes_for_lower_load_factor() {
        assert_eq!(required_bucket_count(11, 0.5, 0), 32);
        assert_eq!(required_bucket_count(15, 0.5, 0), 32);
        assert_eq!(required_bucket_count(33, 0.5, 0), 128);
    }
}

